def solve():
    h, w = map(int, input().split())
    grid = [input() for _ in range(h)]

    def get_neighbors(r, c):
        neighbors = []
        if r > 0:
            neighbors.append((r - 1, c))
        if r < h - 1:
            neighbors.append((r + 1, c))
        if c > 0:
            neighbors.append((r, c - 1))
        if c < w - 1:
            neighbors.append((r, c + 1))
        return neighbors

    def is_valid(r, c):
        return 0 <= r < h and 0 <= c < w

    def bfs(start_r, start_c, target_r, target_c):
        q = [(start_r, start_c, 0)]
        visited = set()
        visited.add((start_r, start_c))

        while q:
            r, c, dist = q.pop(0)

            if r == target_r and c == target_c:
                return True

            for nr, nc in get_neighbors(r, c):
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    if (dist % 2 == 0 and grid[nr][nc] == '#') or (dist % 2 == 1 and grid[nr][nc] == '.'):
                        visited.add((nr, nc))
                        q.append((nr, nc, dist + 1))
        return False

    black_squares = []
    white_squares = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == '#':
                black_squares.append((r, c))
            else:
                white_squares.append((r, c))

    count = 0
    for br, bc in black_squares:
        for wr, wc in white_squares:
            if bfs(br, bc, wr, wc):
                count += 1

    print(count)

