    for u, v in edges:
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)

    def get_distance(start, end):
        q = [(start, 0)]
        visited = {start}
        while q:
            curr, dist = q.pop(0)
            if curr == end:
                return dist
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append((neighbor, dist + 1))
        return float('inf')

    def is_valid(colors):
        for i in range(n):
            for j in range(i + 1, n):
                if get_distance(i, j) <= 2 and colors[i] == colors[j]:
                    return False
        return True

    count = 0
    import itertools
    for colors in itertools.product(range(k), repeat=n):
        if is_valid(colors):
            count = (count + 1) % 1000000007
    print(count)

