def find_max_matches(N, M, p, pairs):
    parent = list(range(N + 1))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for x, y in pairs:
        union(x, y)

    count = 0
    for i in range(1, N + 1):
        if find(i) == find(p[i - 1]):
            count += 1

    ans = 0
    components = {}
    for i in range(1, N+1):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    for root, nodes in components.items():
        cycle_count = 0
        for node in nodes:
            if p[node-1] in nodes:
                cycle_count += 1
        if cycle_count > 0:
            ans += cycle_count
        else:
            ans += 1

    return ans


