def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k
    res = 1
    for i in range(k):
        res = res * (n - i) // (i + 1)
    return res

def count_numbers(n, k):
    s = str(n)
    length = len(s)
    dp = [[[0] * 2 for _ in range(k + 1)] for _ in range(length + 1)]
    dp[0][0][1] = 1
    for i in range(length):
        for j in range(k + 1):
            for l in range(2):
                if dp[i][j][l] == 0:
                    continue
                limit = int(s[i]) if l else 9
                for digit in range(limit + 1):
                    next_j = j + (digit > 0)
                    if next_j > k:
                        continue
                    next_l = l and (digit == limit)
                    if next_j == k and i == length -1 and digit == 0:
                        continue
                    dp[i + 1][next_j][next_l] += dp[i][j][l]
    return dp[length][k][0] + dp[length][k][1]

