        grid[r-1][c-1].append(v)

    dp = [[-1] * C for _ in range(R)]

    def get_max_sum(r, c):
        if r == 0 and c == 0:
            return sum(grid[0][0])
        if r < 0 or c < 0:
            return -1
        if dp[r][c] != -1:
            return dp[r][c]

        max_sum = -1

        # From up
        if r > 0:
            prev_sum = get_max_sum(r-1, c)
            if prev_sum != -1:
                current_sum = prev_sum
                picked_items = grid[r][c]
                picked_items.sort(reverse=True)

                for i in range(min(3, len(picked_items))):
                    current_sum += picked_items[i]

                max_sum = max(max_sum, current_sum)

        # From left
        if c > 0:
            prev_sum = get_max_sum(r, c-1)
            if prev_sum != -1:
                current_sum = prev_sum
                picked_items = grid[r][c]
                picked_items.sort(reverse=True)
                for i in range(min(3, len(picked_items))):
                    current_sum += picked_items[i]
                max_sum = max(max_sum, current_sum)

        dp[r][c] = max_sum
        return max_sum

    print(get_max_sum(R-1, C-1))

solve()

