def is_isomorphic(s, t):
    if len(s) != len(t):
        return False
    mapping_s_t = {}
    mapping_t_s = {}
    for i in range(len(s)):
        char_s = s[i]
        char_t = t[i]
        if char_s in mapping_s_t:
            if mapping_s_t[char_s] != char_t:
                return False
        elif char_t in mapping_t_s:
            if mapping_t_s[char_t] != char_s:
                return False
        else:
            mapping_s_t[char_s] = char_t
            mapping_t_s[char_t] = char_s
    return True

def to_normal_form(s):
    chars = sorted(list(set(s)))
    mapping = {}
    result = ""
    for char in s:
        if char not in mapping:
            mapping[char] = chars.pop(0)
        result += mapping[char]
    return result

