    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def get_subtree(root):
        subtree = set()
        stack = [root]
        subtree.add(root)
        visited = {root}
        while stack:
            curr = stack.pop()
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    subtree.add(neighbor)
                    visited.add(neighbor)
                    stack.append(neighbor)
        return subtree

    counters = [0] * (n + 1)
    for p, x in queries:
        subtree = get_subtree(p)
        for node in subtree:
            counters[node] += x

    print(*counters[1:])

