    for i in range(1, m + 1):
        for j in range(i + 1, m + 1):
            ans = (ans + (abs(i - j) * combinations(m,k,mod) * combinations(n,2,mod)) % mod) % mod

    print((ans * combinations(total_squares,k,mod) * pow(combinations(total_squares,k,mod),mod-2,mod))%mod)

