import heapq

def solve():
    n, m, l = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v, w = map(int, input().split())
        edges.append((u - 1, v - 1, w))
        edges.append((v - 1, u - 1, w))

    q = int(input())
    queries = []
    for _ in range(q):
        s, t = map(int, input().split())
        queries.append((s - 1, t - 1))

    def dijkstra(start, end):
        dist = [[float('inf')] * (n) for _ in range(n)]
        refills = [[float('inf')] * (n) for _ in range(n)]
        dist[start][0] = 0
        refills[start][0] = 0
        pq = [(0, start, 0)]  # (refills, node, fuel_level)

        while pq:
            r, u, fuel = heapq.heappop(pq)

            if r > refills[u][fuel]:
                continue

            if u == end:
                return r

            for v1, v2, w in edges:
                if v1 == u and w <= l:
                    new_fuel = min(l, fuel) - w
                    if new_fuel < 0:
                        continue

                    if refills[v2][new_fuel] > r:
                        refills[v2][new_fuel] = r
                        heapq.heappush(pq, (r, v2, new_fuel))

                    if new_fuel == 0:
                        if refills[v2][l] > r + 1:
                            refills[v2][l] = r + 1
                            heapq.heappush(pq, (r + 1, v2, l))


        return float('inf')

    for s, t in queries:
        result = dijkstra(s, t)
        if result == float('inf'):
            print("-1")
        else:
            print(result)

solve()

