def solve(m, n):
    factors = list(get_prime_factors(m))
    if not factors:
        return 1

    total_ways = 1
    for factor, count in factors:
        ways = combinations(count + n - 1, n - 1)
        total_ways = (total_ways * ways) % MOD
    return total_ways


def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    result = 1
    for i in range(k):
        result = (result * (n - i)) % MOD
        result = (result * pow(i + 1, MOD - 2, MOD)) % MOD
    return result


def get_prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        count = 0
        while n % d == 0:
            count += 1
            n //= d
        if count > 0:
            factors.append((d, count))
        d += 1
    if n > 1:
        factors.append((n, 1))
    return factors

