def find_set(parent, i):
    if parent[i] == i:
        return i
    parent[i] = find_set(parent, parent[i])
    return parent[i]

def union_sets(parent, rank, a, b):
    a_root = find_set(parent, a)
    b_root = find_set(parent, b)
    if a_root != b_root:
        if rank[a_root] < rank[b_root]:
            parent[a_root] = b_root
        elif rank[a_root] > rank[b_root]:
            parent[b_root] = a_root
        else:
            parent[b_root] = a_root
            rank[a_root] += 1

