    indices[x].append(i)


def dp(t, n1, n2, n3):
    if n1 < 0 or n2 < 0 or n3 < 0:
        return 0
    if n1 + n2 + n3 == 0:
        return 1
    if t[n1][n2][n3] != -1:
        return t[n1][n2][n3]
    res = 0
    last_cnt = n1 + n2 + n3
    if last_cnt -1 >= 0:
      if left[last_cnt - 1] + 1 == n1:
          res = (res + dp(t, n1 - 1, n2, n3)) % M
      if left[last_cnt - 1] + 1 == n2:
          res = (res + dp(t, n1, n2 - 1, n3)) % M
      if left[last_cnt - 1] + 1 == n3:
          res = (res + dp(t, n1, n2, n3 - 1)) % M
    t[n1][n2][n3] = res
    return res


def solve():
    heads = [0, 0, 0]
    for i in range(N):
        k = len(indices[i])
        if k == 3:
            heads[0] = heads[1] = heads[2] = i + 1
        elif k == 2:
            heads[0] = heads[1] = i + 1
        elif k == 1:
            heads[0] = i + 1
        else:
            break
    t = np.full((heads[0] + 1, heads[1] + 1, heads[2] + 1), -1, dtype=np.int64)
    base = dp(t, heads[0], heads[1], heads[2])
    return (base * 3) % M


