        for i in range(n):
            for j in range(i + 1, n):
                if gcd(a[i], a[j]) != 1:
                    return False
        return True

    def is_setwise_coprime():
        g = a[0]
        for i in range(1, n):
            g = gcd(g, a[i])
        return g == 1

    if is_pairwise_coprime():
        print("pairwise coprime")
    elif is_setwise_coprime():
        print("setwise coprime")
    else:
        print("not coprime")

