def thickness(n):
    if n == 0:
        return 1
    else:
        return 2 * thickness(n - 1) + 3

def patty(n):
    if n == 0:
        return 1
    else:
        return 2 * patty(n - 1) + 1

def solve(n, x):
    if n == 0:
        return 1 if x == 1 else 0

    burger_thickness = thickness(n)
    half_burger_thickness = (burger_thickness - 3) // 2 + 1

    if x == 1:
        return 0
    elif x <= half_burger_thickness:
        return solve(n - 1, x - 1)
    elif x == half_burger_thickness + 1:
        return patty(n - 1)
    elif x <= burger_thickness - half_burger_thickness:
        return patty(n-1) + solve(n-1, x - half_burger_thickness -1)
    elif x == burger_thickness - half_burger_thickness + 1:
        return patty(n-1) * 2 + 1
    else:
        return patty(n) - solve(n, thickness(n) - x + 1)


