import sys
from collections import deque


def solve(N: int, u: int, v: int, A: "List[int]", B: "List[int]"):
    if u == v:
        return 0
    edges = [[] for _ in range(N)]
    for a, b in zip(A, B):
        edges[a-1].append(b-1)
        edges[b-1].append(a-1)

    dist_t = [-1] * N
    dist_a = [-1] * N

    q = deque([(u - 1, 0)])
    dist_t[u - 1] = 0
    while q:
        curr, d = q.popleft()
        for neighbor in edges[curr]:
            if dist_t[neighbor] == -1:
                dist_t[neighbor] = d + 1
                q.append((neighbor, d + 1))

    q = deque([(v - 1, 0)])
    dist_a[v - 1] = 0
    while q:
        curr, d = q.popleft()
        for neighbor in edges[curr]:
            if dist_a[neighbor] == -1:
                dist_a[neighbor] = d + 1
                q.append((neighbor, d + 1))

    aoki_moves = 0
    takahashi_pos = u - 1
    aoki_pos = v - 1

    while takahashi_pos != aoki_pos:

        best_takahashi_move = -1
        max_takahashi_dist = -1
        for neighbor in edges[takahashi_pos]:
            if dist_t[neighbor] > max_takahashi_dist:
                max_takahashi_dist = dist_t[neighbor]
                best_takahashi_move = neighbor

        takahashi_pos = best_takahashi_move

        if takahashi_pos == aoki_pos:
            break

        aoki_moves += 1

        best_aoki_move = -1
        min_aoki_dist = float('inf')
        for neighbor in edges[aoki_pos]:
            if dist_t[neighbor] < dist_t[aoki_pos] and dist_t[neighbor] < min_aoki_dist:
                min_aoki_dist = dist_t[neighbor]
                best_aoki_move = neighbor

        if best_aoki_move == -1:
            for neighbor in edges[aoki_pos]:
                if dist_t[neighbor] == dist_t[aoki_pos] and neighbor!=takahashi_pos:
                    best_aoki_move = neighbor
                    break

        aoki_pos = best_aoki_move
    return aoki_moves

