    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r
    res = 1
    for i in range(r):
        res = res * (n - i) % mod
        res = res * pow(i + 1, mod - 2, mod) % mod
    return res

