  for i in range(N):
    matches.append(list(map(lambda x: int(x) - 1, input().split())))

  def check(days):
    schedule = [[] for _ in range(days)]
    match_indices = [[0] * (N - 1) for _ in range(N)]

    for day in range(days):
      player_available = [True] * N

      for _ in range(N // 2 + (N % 2)):
        match_found = False
        for p1 in range(N):
          if not player_available[p1]:
            continue

          opponent_index = match_indices[p1][0]
          if opponent_index < N-1:
            p2 = matches[p1][opponent_index]
            if player_available[p2]:
              if p1 < p2:
                schedule[day].append((p1, p2))
                player_available[p1] = False
                player_available[p2] = False
                match_indices[p1][0] += 1

                match_found = True
                break

        if not match_found:
          break


    total_matches = 0
    for day in schedule:
      total_matches += len(day)

    if total_matches != N * (N - 1) // 2:
        return False

    return True

  low, high = 1, N - 1
  ans = -1
  while low <= high:
    mid = (low + high) // 2
    if check(mid):
      ans = mid
      high = mid - 1
    else:
      low = mid + 1

  return ans
