import math

def comb(n, r):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r
    res = 1
    for i in range(r):
        res = res * (n - i) // (i + 1)
    return res

