MOD = 998244353


def main():
    N, S = map(int, input().split())
    A = list(map(int, input().split()))
    dp = [[0] * (S + 1) for _ in range(N + 1)]
    dp[0][0] = 1
    for i in range(N):
        for j in range(S + 1):
            dp[i + 1][j] += dp[i][j]
            dp[i + 1][j] %= MOD
            if j + A[i] <= S:
                dp[i + 1][j + A[i]] += dp[i][j]
                dp[i + 1][j + A[i]] %= MOD
    ans = 0
    for i in range(1, 1 << N):
        subset_sum = 0
        subset_count = 0
        subset_arr = []
        for j in range(N):
            if (i >> j) & 1:
                subset_arr.append(A[j])
        subset_dp = [0] * (S + 1)
        subset_dp[0] = 1
        for num in subset_arr:
            for k in range(S, num - 1, -1):
                subset_dp[k] += subset_dp[k - num]
                subset_dp[k] %= MOD
        ans += subset_dp[S]
        ans %= MOD
    print(ans)


