        neighbor_list[b-1].append(a-1)
    return neighbor_list

def paint(K, nlist, node, parent, colors):
    mod = 1000000007
    count = 0
    for color in range(K):
        valid = True
        if parent != -1 and colors[parent] == color:
            valid = False
        for neighbor_node in nlist[node]:
            if neighbor_node != parent and colors[neighbor_node] == color:
                valid = False
        if valid:
            colors[node] = color

            next_node = -1
            all_painted = True
            for i in range(len(colors)):
                if colors[i] == -1:
                    next_node = i
                    all_painted = False
                    break

            if all_painted:
                count = (count + 1) % mod
            else:
                count = (count + paint(K, nlist, next_node, node, colors)) % mod
            colors[node] = -1
    return count

