def count_patties(n, x):
    if n == 0:
        return 1 if x != 0 else 0
    num_layers = 2 ** (n + 1) - 1
    if x >= num_layers:
        return 2 ** n
    mid = num_layers // 2
    if x == mid:
        return 2 ** n - 1
    elif x < mid:
        return count_patties(n - 1, x - 1)
    else:
        return 2 ** n - 1 + 1 + count_patties(n - 1, x - mid - 1)

