from collections import deque

def fennec_vs_snuke(n, edges):
    adj_list = [[] for _ in range(n + 1)]
    for a, b in edges:
        adj_list[a].append(b)
        adj_list[b].append(a)

    black = set()
    white = set()
    queue = deque([1])
    while queue:
        node = queue.popleft()
        if node in black:
            for neighbor in adj_list[node]:
                if neighbor not in black:
                    black.add(neighbor)
                    queue.append(neighbor)
        else:
            for neighbor in adj_list[node]:
                if neighbor not in white:
                    white.add(neighbor)
                    queue.append(neighbor)

    if len(black) > len(white):
        return "Fennec"
    else:
        return "Snuke"

