from collections import deque

def bfs(graph, start, end):
    queue = deque([(start, 0)])
    visited = set()

    while queue:
        node, steps = queue.popleft()

        if node == end:
            return steps

        if node in visited:
            continue

        visited.add(node)

        for neighbor in graph[node]:
            queue.append((neighbor, steps + 1))

    return -1

