import math
import itertools
def fact(n):  
    if (n <= 1): 
        return 1

    return n * fact(n - 1)  

def nPr(n, r):  

    return nCr(n) / nCr(r)

def nCr(n, r):
    p = 1
    k = 1

    if (n - r < r): 
        r = n - r 

    if (r != 0):  
        while (r): 
            p *= n 
            k *= r 

            m = math.gcd(p, k) 

            p //= m 
            k //= m 

            n -= 1
            r -= 1

    else: 
        p = 1

    return p 

