def dp(t, n1, n2, n3):
    remaining = n1 + n2 + n3
    if remaining < 0:
        return 0
    cached = t[n1, n2, n3]
    if cached >= 0:
        return cached
    last_cnt = left[remaining]
    res = 0
    if last_cnt == n1:
        res += dp(t, n1-1, n2, n3)
        res %= M
    if last_cnt == n2:
        res += dp(t, n1, n2-1, n3)
        res %= M
    if last_cnt == n3:
        res += dp(t, n1, n2, n3-1)
        res %= M
    t[n1, n2, n3] = res
    return res


