    AB = [R() for _ in range(N-1)]
    tree = [[] for _ in range(N)]
    for a, b in AB:
        tree[a-1].append(b-1)
        tree[b-1].append(a-1)
    task = [(i, [0]) for i in tree[0]]
    arrived = [0] * N
    arrived[0] = 1
    while task:
        node, parent = task.pop()
        for child in tree[node]:
            if child == N-1:
                way = parent + [node, N-1]
                break
            if arrived[child] == 0:
                arrived[child] = 1
                task.append((child, parent+[node]))
    kireme = way[(len(way)-1)//2]
    kireme_ikenai = way[(len(way)-1)//2+1]

    cnt = 0
    task = [0]
    arrived = [0] * N
    while task:
        node = task.pop()
        cnt += 1
        arrived[node] = 1
        for child in tree[node]:
            if child == kireme_ikenai:
                continue
            else:
                if not arrived[child]:
                    task.append(child)
    if cnt > N - cnt:
        print('Fennec')
    else:
        print('Snuke')


