def factorize(n):
    res = []
    p = 2
    while p * p <= n:
        if n % p == 0:
            cnt = 0
            while n % p == 0:
                cnt += 1
                n //= p
            res.append(p)
        p += 1
    if n > 1:
        res.append(n)
    return res


def solve():
    N = int(input())

    c = 0
    for i in range(1, N + 1, 2):
        f = factorize(i)
        l = []
        for j in f:
            l.append(j)
            l.append(i // j)
        l.append(i)
        l.append(1)
        s = len(set(l))
        if s == 8:
            c += 1

    return c


