    N = NI()
    AB = defaultdict(int)
    Y, Z = 0, 0
    for i in range(N):
        a, b = NMI()
        if a == b == 0:
            Z += 1
            continue
        if b == 0:
            Y += 1
            continue

        if Fraction(a, b) in AB:
            AB[Fraction(a, b)] += 1
        else:
            AB[Fraction(a, b)] = 1

    C = defaultdict(lambda: (0, 0))
    ans = 1
    for ab, k in AB.items():
        a = ab.numerator
        b = ab.denominator
        if a > 0:
            if Fraction(-b, a) in AB:
                t = AB[Fraction(-b, a)]
            else:
                t = 0
        elif a < 0:
            if Fraction(b, -a) in AB:
                t = AB[Fraction(b, -a)]
            else:
                t = 0
        else:
            t = Y
        C[(a, b)] = (k, t)

    for k, t in C.values():
        tmp = pow(2, k, MOD) + pow(2, t, MOD) - 1
        ans = (ans * tmp) % MOD
    print((ans + Z - 1) % MOD)

