def is_8_factors(n):
    if int(math.sqrt(n)) ** 2 == n:
        divisors = 3
    else:
        divisors = 2
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                divisors += 1
            else:
                divisors += 2
            if divisors > 8:
                return False
    return divisors == 8

