    C.sort(reverse=True)
    traversal_order=[0]*n
    visited=[0]*n
    stack=[0]
    order_list=[]
    while stack:
        current_node = stack.pop()
        visited[current_node]=1
        order_list.append(current_node)
        for neighbor in graph[current_node]:
            if not visited[neighbor]:
                stack.append(neighbor)
    order_values={}
    for i in range(n):
        traversal_order[order_list[i]]=C[i]
        order_values[C[i]]=1
    current_index=0
    for i in range(n):
        if traversal_order[i] in order_values:
            traversal_order[i]=C[current_index]
            current_index+=1
    ans=0
    for i in range(n-1):
        a,b=AB[i]
        ans+=min(traversal_order[a-1],traversal_order[b-1])
    print(ans)
    print(' '.join(map(str,traversal_order)))

