def search(nums):
	left = min(nums)
	right = max(nums)
	while left < right:
		mid = (left + right) // 2
		if calc(nums, mid) > calc(nums, mid+1):
			left = mid + 1
		else:
			right = mid
	return left

def calc(nums, i):
	return sum([abs(x - i) for x in nums])

