def count_pairs(H, W, grid):
    from collections import deque

    black = []
    white = []

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                black.append((i, j))
            else:
                white.append((i, j))

    visited = [[-1] * W for _ in range(H)]

    def bfs(start_i, start_j, color):
        queue = deque([(start_i, start_j)])
        visited[start_i][start_j] = color
        reachable = []
        while queue:
            x, y = queue.popleft()
            reachable.append((x, y))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and visited[nx][ny] == -1:
                    if grid[nx][ny] != grid[x][y]:  # ensure alternating colors
                        visited[nx][ny] = color
                        queue.append((nx, ny))
        return reachable

    black_groups = []
    white_groups = []

    for i, j in black:
        if visited[i][j] == -1:
            group = bfs(i, j, 0)
            black_groups.append(set(group))

    for i, j in white:
        if visited[i][j] == -1:
            group = bfs(i, j, 1)
            white_groups.append(set(group))

    pairs_count = 0
    for b_group in black_groups:
        for w_group in white_groups:
            if b_group & w_group:  # existence of common cells
                pairs_count += len(b_group) * len(w_group)

    return pairs_count

