def dijkstra(start):
    dp = [float('inf')] * 10
    dp[start] = 0
    heap = [(0, start)]

    while heap:
        curr_cost, node = heapq.heappop(heap)

        if curr_cost > dp[node]:
            continue

        for next_node in range(10):
            if node != next_node:  
                cost_to_next = cost[node][next_node]
                new_cost = curr_cost + cost_to_next
                if new_cost < dp[next_node]:
                    dp[next_node] = new_cost
                    heapq.heappush(heap, (new_cost, next_node))

    return dp

