def construct_graph(N, K):
    if K > (N - 2) * (N - 1) / 2 or K < 0:
        return -1

    edges = []

    # Create a base star graph to ensure it's connected
    for i in range(2, N + 1):
        edges.append((1, i))

    # Now we need to create K pairs of distance 2
    pairs_count = 0

    # Using the star's leaves to form the distance 2 pairs
    for i in range(2, N + 1):
        for j in range(i + 1, N + 1):
            if pairs_count < K and j not in {1, i}:
                edges.append((i, j))
                pairs_count += 1
                if pairs_count >= K:
                    break
        if pairs_count >= K:
            break

    M = len(edges)
    if pairs_count == K:
        result = [str(M)]
        for u, v in edges:
            result.append(f"{u} {v}")
        return "\n".join(result)

    return -1

