    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]  # right, up, left, down
    pos = (0, 0)
    direction_index = 0

    for move in s:
        if move == 'F':
            pos = (pos[0] + directions[direction_index][0], pos[1] + directions[direction_index][1])
