def print_grid(A, B):
    # Determine grid dimensions
    h, w = 1, 1
    while h * w < A + B:
        if h < w:
            h += 1
        else:
            w += 1

    grid = [['#' for _ in range(w)] for _ in range(h)]

    def fill_white_components(num_components):
        count = 0
        for i in range(h):
            for j in range(w):
                if count < num_components and (i % 2 == 0 and j % 2 == 0):
                    grid[i][j] = '.'
                    count += 1
                if count == num_components:
                    return

    def fill_black_components(num_components):
        count = 0
        for i in range(h):
            for j in range(w):
                if count < num_components and (i % 2 == 1 and j % 2 == 1):
                    grid[i][j] = '#'
                    count += 1
                if count == num_components:
                    return

    fill_white_components(A)
    fill_black_components(B)

    print(h, w)
    for row in grid:
        print(''.join(row))

