def count_painting_ways(N, S1, S2):
    MOD = 1000000007

    # Create a graph representation of the dominoes
    adj = {}
    for i in range(N):
        if (i, 0) not in adj:
            adj[(i, 0)] = set()
        if (i, 1) not in adj:
            adj[(i, 1)] = set()

        if i < N - 1:
            if S1[i] == S1[i + 1]:
                adj[(i, 0)].add((i + 1, 0))
                adj[(i + 1, 0)].add((i, 0))
            if S2[i] == S2[i + 1]:
                adj[(i, 1)].add((i + 1, 1))
                adj[(i + 1, 1)].add((i, 1))
            if S1[i] == S2[i + 1]:
                adj[(i, 0)].add((i + 1, 1))
                adj[(i + 1, 0)].add((i, 1))
            if S2[i] == S1[i + 1]:
                adj[(i, 1)].add((i + 1, 0))
                adj[(i + 1, 1)].add((i, 0))

    def dfs(node, color, visited):
        visited.add(node)
        total_ways = 1
        for neighbor in adj[node]:
            if neighbor not in visited:
                total_ways *= 2
                total_ways %= MOD
                total_ways *= dfs(neighbor, 1 - color, visited)
                total_ways %= MOD
        return total_ways

    visited = set()
    ways = 1

    for i in range(N):
        for j in range(2):
            if (i, j) not in visited:
                ways *= dfs((i, j), 0, visited)
                ways %= MOD

    return ways

