def max_score(N, K, R, S, P, T):
    scores = {'r': S, 'p': R, 's': P}
    dp = [[0]*3 for _ in range(N+1)]

    for i in range(1, N+1):
        current = T[i-1]
        max_score_hand = 0

        for j in range(3):
            hand = chr(j + ord('r'))  # 'r' -> 0, 'p' -> 1, 's' -> 2
            if (i > K and hand == T[i-K-1]) or (i <= K and i == 1 and hand != current):
                continue
            if hand == 'r' and current == 's':
                score = R
            elif hand == 'p' and current == 'r':
                score = P
            elif hand == 's' and current == 'p':
                score = S
            else:
                score = 0

            max_score_hand = max(max_score_hand, dp[i-1][j] + score)

        dp[i][0] = max_score_hand
        for j in range(1, 3):
            dp[i][j] = max(dp[i-1][j], dp[i][0])

    return max(dp[N])

