def distinct_strings_after_reverse(s):
    n = len(s)
    unique_strings = set([s])  # Start with the original string

    for i in range(n):
        for j in range(i, n):
            # Reverse the substring from index i to j
            reversed_substring = s[i:j + 1][::-1]
            new_string = s[:i] + reversed_substring + s[j + 1:]
            unique_strings.add(new_string)

