def find_bills(N, Y):
    max_10000 = min(N, Y // 10000)
    for x in range(max_10000 + 1):
        remaining_value = Y - x * 10000
        remaining_bills = N - x
        if remaining_value < 0 or remaining_bills < 0:
            continue
        max_5000 = min(remaining_bills, remaining_value // 5000)
        for y in range(max_5000 + 1):
            z = remaining_bills - y
            if z < 0:
                continue
            if remaining_value - y * 5000 == z * 1000:
                return x, y, z
    return -1, -1, -1

