def count_amidakuji(H, W, K):
    MOD = 1000000007

    if W == 1:
        return 1

    dp = [[0] * (W + 1) for _ in range(H + 1)]
    dp[0][1] = 1

    for h in range(1, H + 1):
        for w in range(1, W + 1):
            dp[h][w] = dp[h - 1][w]
            if w > 1:
                dp[h][w] = (dp[h][w] + dp[h - 1][w - 1]) % MOD
            if w < W:
                dp[h][w] = (dp[h][w] + dp[h - 1][w + 1]) % MOD

    result = 0
    for w in range(1, W + 1):
        if w == K:
            result = (result + dp[H][w]) % MOD

    return result

