def find_shortest_path_length(n, A):
    total_length = 0
    for u in range(n):
        for v in range(u + 1, n):
            if A[u][v] < 0:
                return -1

            # Check if there's a path that is shorter than the direct edge
            for k in range(n):
                if k != u and k != v:
                    if A[u][v] > A[u][k] + A[k][v]:
                        return -1

            # If A[u][v] is a direct edge, add it to the total length
            direct_edge = True
            for k in range(n):
                if k != u and k != v:
                    if A[u][v] == A[u][k] + A[k][v]:
                        direct_edge = False
                        break
            if direct_edge:
                total_length += A[u][v]

    return total_length

