def count_patties(N, X):
    if N == 0:
        return 0

    # Number of layers in level-N burger
    layers_in_level_N = 1 if N == 0 else 2 * count_layers(N - 1) + 2

    if X <= 0:
        return 0
    if X >= layers_in_level_N:
        return count_patties(N)  # All patties in level-N burger

    # Recursive breakdown
    half_layers = count_layers(N - 1)

    if X <= half_layers + 1:
        return count_patties(N - 1, X - 1)
    else:
        return count_patties(N - 1, half_layers) + 1 + count_patties(N - 1, X - half_layers - 1)

def count_layers(N):
    if N == 0:
        return 1
    return 2 * count_layers(N - 1) + 2

