def min_cuts(H, W, K, grid):
    def count_whites(rows):
        return sum(sum(grid[r][c] == '1' for c in range(W)) for r in rows)

    cuts = 0
    row_blocks = list(range(H))

    def can_cut(rows):
        return count_whites(rows) <= K

    # Process horizontal cuts
    start = 0
    while start < H:
        end = start
        while end < H and can_cut(range(start, end + 1)):
            end += 1
        if end - start > 0:
            cuts += (end - start - 1)
        start = end

    # Process vertical cuts
    for col in range(W):
        start = 0
        while start < H:
            end = start
            while end < H and can_cut(range(start, end + 1)):
                end += 1
            if end - start > 0:
                cuts += (end - start - 1)
            start = end

    return cuts

