def next_char(S, K):
    transform = {str(i): str(i) * i for i in range(1, 10)}
    day_limit = 5 * 10**15

    def length_after_days(x, days):
        if days == 0:
            return len(x)
        return sum(length_after_days(transform[c], days - 1) for c in x)

    while day_limit > 0:
        total_length = length_after_days(S, day_limit)

        if total_length < K:
            break

        for i, char in enumerate(S):
            char_len = length_after_days(char, day_limit)
            if K <= char_len:
                S = transform[char]
                day_limit -= 1
                break
            K -= char_len

    return S[K - 1]

