def can_schedule_tournament(N, matches):
    from collections import defaultdict

    match_schedule = defaultdict(list)

    # Create an adjacency list for matches
    for player in range(N):
        for opponent in matches[player]:
            match_schedule[player + 1].append(opponent)

    days = 0
    remaining_matches = {player: set(match_schedule[player]) for player in range(1, N + 1)}

    while any(remaining_matches.values()):
        days += 1
        played_today = set()
        for player in range(1, N + 1):
            if remaining_matches[player]:
                for opponent in remaining_matches[player]:
                    if opponent not in played_today:
                        played_today.add(player)
                        played_today.add(opponent)
                        remaining_matches[player].remove(opponent)
                        remaining_matches[opponent].remove(player)
                        break

    for player in range(1, N + 1):
        if remaining_matches[player]:
            return -1

    return days

