def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def preprocess(max_n):
    similar_count = [0] * (max_n + 1)
    count = 0

    for i in range(1, max_n + 1, 2):
