def max_product_modulo(N, K, A):
    MOD = 10**9 + 7
    A.sort()

    if K == N:
        product = 1
        for num in A:
            product = product * num % MOD
        return product

    max_product = 1
    negative_count = sum(1 for x in A if x < 0)

    if negative_count == 0 or (negative_count % 2 == 0 and K % 2 == 1):
        # Choose K largest positives or K smallest negatives
        for num in A[-K:]:
            max_product = max_product * num % MOD
    elif negative_count % 2 == 1 and K % 2 == 0:
        # Case where we have an odd number of negatives, need to take one less negative
        if negative_count < K:
            # Take the largest K from positives and even number of negatives
            for num in A[-K:]:
                max_product = max_product * num % MOD
        else:
            # Take K negatives (choose K-1 negatives and 1 largest positive)
            product_with_negatives = 1
            for num in A[:K]:
                product_with_negatives = product_with_negatives * num % MOD
            for num in A[-1:]:
                product_with_negatives = product_with_negatives * num % MOD
            max_product = max(max_product, product_with_negatives)    
    else:
        # We can take all from negatives and at least one positive
        for num in A[-K:]:
            max_product = max_product * num % MOD

    return max_product

