def bfs(start):
    queue = deque([start])
    visited = {start}
    depth_count = 0

    while queue:
        current_level_size = len(queue)
        depth_count += 1
        for _ in range(current_level_size):
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    return depth_count - 1

