def min_bridges_to_remove(N, M, requests):
    disjoint_set = list(range(N + 1))

    def find(x):
        if disjoint_set[x] != x:
            disjoint_set[x] = find(disjoint_set[x])
        return disjoint_set[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            disjoint_set[root_y] = root_x

    edges_to_remove = set()

    for a, b in requests:
        for i in range(a, b):
            edges_to_remove.add(i)

    result = 0
    for i in range(1, N):
        if i not in edges_to_remove:
            union(i, i + 1)

    for a, b in requests:
        if find(a) == find(b):
            result += 1

    return result

