    return pow(x, mod - 2, mod)

def count_bouquets(n, a, b):
    mod = 10**9 + 7

    total_bouquets = pow(2, n, mod) - 1
    total_bouquets = (total_bouquets + mod) % mod

    if a <= n:
        bouquets_a = mod_inv(1, mod) if a == 0 else pow(2, n - a, mod)
        total_bouquets = (total_bouquets - bouquets_a + mod) % mod

    if b <= n:
        bouquets_b = mod_inv(1, mod) if b == 0 else pow(2, n - b, mod)
        total_bouquets = (total_bouquets - bouquets_b + mod) % mod

    if a + b <= n:
        bouquets_ab = mod_inv(1, mod) if a + b == 0 else pow(2, n - (a + b), mod)
        total_bouquets = (total_bouquets + bouquets_ab) % mod

    return total_bouquets

