def main(sample_file=''):
    import sys
    from collections import deque

    sys.setrecursionlimit(10**7)

    r = lambda: sys.stdin.readline().strip()
    r_int = lambda: int(r())
    R = lambda: list(map(int, r().split()))

    if sample_file:
        sys.stdin = open(sample_file)

    N = r_int()
    AB = [R() for _ in range(N-1)]
    tree = [[] for _ in range(N)]
    for a, b in AB:
        tree[a-1].append(b-1)
        tree[b-1].append(a-1)

    # BFS to find the path from 1 to N
    def bfs(start, target):
        queue = deque([start])
        parents = {start: None}
        while queue:
            node = queue.popleft()
            if node == target:
                break
            for neighbor in tree[node]:
                if neighbor not in parents:
                    parents[neighbor] = node
                    queue.append(neighbor)

        path = []
        while target is not None:
            path.append(target)
            target = parents[target]
        return path[::-1]

    path = bfs(0, N-1)
    kireme = path[len(path) // 2]

    cnt = 0
    arrived = [0] * N
    task = [0]
    while task:
        node = task.pop()
        cnt += 1
        arrived[node] = 1
        for child in tree[node]:
            if child != kireme and not arrived[child]:
                task.append(child)

    if cnt > N - cnt:
        print('Fennec')
    else:
        print('Snuke')

