def max_gcd_after_replacement(l):
    l = list(set(l))  # Get unique values
    if len(l) == 1:
        return l[0]

    overall_gcd = gcd_lis(l)
    max_gcd = overall_gcd

    for num in l:
        modified_l = [num] + [x for x in l if x != num]
        max_gcd = max(max_gcd, gcd_lis(modified_l))

    return max_gcd

