import sys
from collections import defaultdict
readline = sys.stdin.readline

def main():
    n = int(readline())
    a = [list(map(int, readline().split())) for _ in range(n)]

    # Initialize the weight of edges
    wts = dict(((i, j), a[i][j]) for i in range(n) for j in range(n) if i != j)

    # Floyd-Warshall algorithm to determine the actual shortest paths
    cost = defaultdict(lambda: float('inf'))
    for i in range(n):
        for j in range(n):
            if i == j:
                cost[(i, j)] = 0
            elif (i, j) in wts:
                cost[(i, j)] = wts[(i, j)]

    for k in range(n):
        for i in range(n):
            for j in range(n):
                cost[(i, j)] = min(cost[(i, j)], cost[(i, k)] + cost[(k, j)])

    edges = [e for e in wts.keys() if e[0] < e[1]]
    edges.sort(key=wts.get, reverse=True)

    s = 0
    for e in edges:
        # If the shortest distance is less than the weight, it's invalid
        if cost[e] < wts[e]:
            print(-1)
            return

        # Check for detours
        detour = min(cost[(e[0], i)] + cost[(i, e[1])] for i in range(n) if i != e[0] and i != e[1])
        if detour > cost[e]:
            s += wts[e]

    print(s)

