import sys, math, bisect
sys.setrecursionlimit(300000)


def solve(N: int, D: int, A: int, X: "List[int]", H: "List[int]"):
    p = []
    for i in range(N):
        p.append([X[i], H[i]])
    p.sort()
    ret = 0
    nex = 0
    l = 0
    minus = 0
    curr_health = 0

    for i in range(N):
        while nex < N and p[nex][0] <= p[i][0] + D:
            curr_health += max(0, p[nex][1])
            nex += 1

        remaining_health = max(0, p[i][1] - curr_health)
        if remaining_health > 0:
            bombs_needed = math.ceil(remaining_health / A)
            ret += bombs_needed
            curr_health += bombs_needed * A

        for j in range(i, nex):
            p[j][1] = max(0, p[j][1] - bombs_needed * A)

    print(ret)
    return

def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    D = int(next(tokens))  # type: int
    A = int(next(tokens))  # type: int
    X = [int()] * (N)  # type: "List[int]"
    H = [int()] * (N)  # type: "List[int]"
    for i in range(N):
        X[i] = int(next(tokens))
        H[i] = int(next(tokens))
    solve(N, D, A, X, H)

