import sys
from collections import deque,defaultdict

H,W,K=map(int, sys.stdin.readline().split())
ichigo=[]
tate_ichigo=set()
cnt=0
h_visit=[0 for h in range(H)]  #縦軸にイチゴがない箇所は0、ある箇所は1
L=[ [] for h in range(H) ]
for h in range(H):
    s=sys.stdin.readline().strip()
    for w,x in enumerate(s):
        if x==".":
            L[h].append(0)
        elif x=="#":
            cnt+=1
            L[h].append(cnt)
            ichigo.append((h,w))
            h_visit[h]=1
            tate_ichigo.add(h)

D=(1,-1)
for h,w in ichigo:
    num=L[h][w]
    Visit=defaultdict(lambda: 0) #訪問した頂点
    q=deque()
    q.append((h,w))
    Visit[(h,w)]=1

    while q:
        h,w=q.popleft()
        for dw in D:
            if 0<=w+dw<W:   #マスの横にはみださないように
                if L[h][w+dw]==0 and Visit[(h,w+dw)]==0:
                    Visit[(h,w+dw)]=1	#訪問済みVisitに1をセットする。4行上のpopleftの直後でVisitをセットすると同じ頂点がqに入り、TLEする
                    L[h][w+dw]=num
                    q.append((h,w+dw))

#1行全部0の行を、値ありの行で埋めるためのdfs
def dfs(h):
    if h==0 or h==H-1: return
    for dh in D:
        if h_visit[h+dh]==0:
            h_visit[h+dh]=1
            L[h+dh]=L[h]
            dfs(h+dh)

for h in tate_ichigo:
    dfs(h)

result = [[0] * W for _ in range(H)]
for l in range(H):
    for x in range(W):
        if L[l][x] != 0:
            result[l][x] = L[l][x]

