def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def max_gcd_after_replacement(arr):
    overall_gcd = arr[0]
    for num in arr[1:]:
        overall_gcd = gcd(overall_gcd, num)

    max_possible_gcd = overall_gcd
    for num in arr:
        modified_gcd = gcd(overall_gcd, num)
        if modified_gcd > max_possible_gcd:
            max_possible_gcd = modified_gcd

    return max_possible_gcd

