def neighbor(N, edges):
    neighbor_list = [[] for _ in range(N)]
    for a, b in edges:
        neighbor_list[a-1].append(b-1)
        neighbor_list[b-1].append(a-1)

    return neighbor_list


def paint(K, nlist, now_num, from_num):
        mod = 1000000007
        if from_num == -1:
            can_use_color = K - 1
        else:
            can_use_color = K - 2

        case_num = 1
        if len(nlist[now_num]) > can_use_color + 1 or (len(nlist[now_num]) == 1 and from_num != -1):
            return 0

        for child in nlist[now_num]:
            if child == from_num:
                continue
            case_num *= can_use_color
            case_num %= mod
            can_use_color -= 1

        for child in nlist[now_num]:
            if child == from_num:
                continue
            case_num *= paint(K, nlist, child, now_num)
            case_num %= mod

        return case_num


