def construct_sequence(M, K):
    n = 2 ** (M + 1)
    seq = []

    # Create the required sequence if possible
    for i in range(2 ** M):
        seq.append(i)
        seq.append(i)

    # To satisfy the XOR condition, we need to reorder the sequence
    for i in range(0, n, 2):
        seq[i], seq[i + 1] = seq[i + 1], seq[i]

    # Check the XOR condition
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if seq[i] == seq[j]:
                if i < j:
                    xor_result = 0
                    for k in range(i, j + 1):
                        xor_result ^= seq[k]
                    if xor_result != K:
                        return -1  # The condition is not met

    return seq

