def slove():
    import sys
    input = sys.stdin.readline
    from math import gcd, isqrt

    a, b = list(map(int, input().rstrip('\n').split()))
    common_gcd = gcd(a, b)

    def count_coprime_divisors(n):
        count = 0
        for d in range(1, isqrt(n) + 1):
            if n % d == 0:
                count += 1
                if d != n // d:
                    count += 1
        return count

    count = count_coprime_divisors(common_gcd)
    print(count)

