import sys


def solve(N: int, K: int, S: int):
    if K==0:
        if S>N:
            ans=[0]*N
        else:
            ans=[N+1]*N
    elif K==N:
        ans=[S]*N

    else:
        for i in range(N):
            yok=0
            if i<K:
                ans[i]=S
            else:
                ans[i]=1
                yok+=1

        ans[K-1]-=yok

    for i in range(N):
        print(ans[i],end=" ")

    return


