import sys


def solve(N: int, A: "List[int]"):
    for i in range(N+1):
        if A[i] > 2**i:
            print(-1)
            return
        elif A[i] == 2**i and i != N:
            print(-1)
            return
        else:
            continue

    if N == 0:
        print(1)
        return

    safe_line = [0]*(N+1)
    safe_line[N] = A[N]

    for i in range(N-1,-1,-1):
        safe_line[i] = safe_line[i+1]+A[i]

    node_count = [0]*(N+1)
    node_count[0] = 1
    answer = 1

    for i in range(1,N+1):
        if node_count[i-1]*2 > safe_line[i]:
            node_count[i] = safe_line[i]
            answer += node_count[i]
            node_count[i] -= A[i]
        else:
            node_count[i] = node_count[i-1]*2
            answer += node_count[i]
            node_count[i] -= A[i]

    print(answer)

    return


