def snk_check(lst):
    flag = 0
    if len(lst) == 1:
        return lst

    for i in range(len(lst) - 1):
        if lst[i] + 1 != lst[i+1]:
            del lst[i+1]
            flag = 1
            break
    if flag == 1:
        ans = lst[i:]  # breakした = 不合格、再検査が必要
    else:
        ans = lst[-1]  # breakせずに完走した = 合格,末尾の数値がリストの長さと一致するので、それを返す
    return ans


